import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline


# ---------- Custom CUDA source for matmul Q @ K^T ----------
matmul_qk_cuda_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void matmul_qk_kernel(const float* Q, const float* K, float* out, int B, int H, int S, int D) {
    int b = blockIdx.z;
    int h = blockIdx.y;
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= B * H * S * D) return;
    float sum = 0.0f;
    for (int d = 0; d < D; ++d) {
        int q = (idx % S);
        int q_offset = b * H * S * D + h * S * D + q * D + d;
        int k = (idx / (S * D));
        int k_offset = b * H * S * D + h * D * S + k * D + d;
        sum += Q[q_offset] * K[k_offset];
    }
    out[idx] = sum;
}

torch::Tensor matmul_qk_cuda(torch::Tensor Q, torch::Tensor K) {
    auto B = Q.size(0);
    auto H = Q.size(1);
    auto S = Q.size(2);
    auto D = Q.size(3);
    auto out = torch::empty(Q.size());
    auto temp = torch::empty(B * H * S * S * sizeof(float));
    const int BLOCK = 256;
    const int numBlocksX = (S + BLOCK - 1) / BLOCK;
    const int numBlocksY = (H + BLOCK - 1) / BLOCK;
    const int numBlocksZ = (B + BLOCK - 1) / BLOCK;
    matmul_qk_kernel<<<numBlocksX, BLOCK, numBlocksY, BLOCK, numBlocksZ, BLOCK>>>(
        Q.data_ptr<float>(), K.data_ptr<float>(), temp.data_ptr<float>(),
        B, H, S, D
    );
    auto out_shape = list(temp.shape);
    out_shape[2] = S; out_shape[3] = S;
    out = temp.contiguous().view(out_shape);
    return out;
}
"""

# ---------- Custom CUDA source for element-wise softmax ----------
softmax_cuda_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void softmax_kernel(float* scores, float* exp_scores, int N) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < N) {
        exp_scores[idx] = expf(scores[idx]);
    }
}

torch::Tensor softmax_cuda(torch::Tensor scores, int dim) {
    auto N = scores.numel();
    auto out = torch::zeros_like(scores);
    auto exp_scores = torch::empty(N * sizeof(float));
    const int BLOCK = 256;
    const int numBlocks = (N + BLOCK - 1) / BLOCK;
    softmax_kernel<<<numBlocks, BLOCK>>>(
        scores.data_ptr<float>(), exp_scores.data_ptr<float>(),
        N
    );
    return out;
}
"""

# ---------- Custom CUDA source for matmul V (weighted sum) ----------
matmul_v_cuda_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void matmul_v_kernel(const float* attn_weights, const float* V, float* out, int B, int H, int S, int D) {
    int b = blockIdx.z;
    int h = blockIdx.y;
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= B * H * S * D) return;
    float sum = 0.0f;
    for (int k = 0; k < S; ++k) {
        int q = (idx % S);
        int q_offset = b * H * S * D + h * S * D + q * D + 0;
        int k_offset = b * H * S * D + h * D * S + k * D + 0;
        sum += attn_weights[q_offset] * V[k_offset];
    }
    out[idx] = sum;
}

torch::Tensor matmul_v_cuda(torch::Tensor attn_weights, torch::Tensor V) {
    auto B = attn_weights.size(0);
    auto H = attn_weights.size(1);
    auto S = attn_weights.size(2);
    auto D = V.size(3);
    auto out = torch::empty(V.size());
    auto temp = torch::empty(B * H * S * D * sizeof(float));
    const int BLOCK = 256;
    const int numBlocksX = (S + BLOCK - 1) / BLOCK;
    const int numBlocksY = (H + BLOCK - 1) / BLOCK;
    const int numBlocksZ = (B + BLOCK - 1) / BLOCK;
    matmul_v_kernel<<<numBlocksX, BLOCK, numBlocksY, BLOCK, numBlocksZ, BLOCK>>>(
        attn_weights.data_ptr<float>(), V.data_ptr<float>(),
        temp.data_ptr<float>(),
        B, H, S, D
    );
    auto out_shape = list(temp.shape);
    out_shape[2] = S; out_shape[3] = D;
    out = temp.contiguous().view(out_shape);
    return out;
}
"""

