class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()
        self.matmul_qk = matmul_qk
        self.softmax = softmax
        self.matmul_v = matmul_v

    def forward(self, Q: torch.Tensor, K: torch.Tensor, V: torch.Tensor) -> torch.Tensor:
        # Q,K,V: (batch, num_heads, seq_len, embed_dim)
        scores = self.matmul_qk(Q, K)               # (B,H,S,S)
        scale = 1.0 / torch.sqrt(V.size(-1))       # 1/sqrt(embed_dim)
        scores = scores * scale
        attn_weights = self.softmax(scores, dim=2)  # softmax over seq length (axis=2)
        out = self.matmul_v(attn_weights, V)       # (B,H,S,embed_dim)
        return out

